static irqreturn_t rswitch_data_irq ( struct rswitch_private * priv , u32 * dis ) { struct rswitch_gwca_queue * gq ; int i , index , bit ; for ( i = 0 ; i < priv -> gwca . num_queues ; i ++ ) { gq = & priv -> gwca . queues [ i ] ; index = gq -> index / 32 ; bit = BIT ( gq -> index % 32 ) ; if ( ! ( dis [ index ] & bit ) ) { continue ; } rswitch_ack_data_irq ( priv , gq -> index ) ; rswitch_queue_interrupt ( gq -> ndev , NULL ) ; } return IRQ_HANDLED ; } 